   586	/**
   587	 * Remove only the detached cross-host snapshot shape created by the managed
   588	 * adapter. The canonical tmp boundary is checked before either git metadata or
   589	 * filesystem state is touched, so a persisted caller-controlled cwd cannot
   590	 * turn retention GC into an arbitrary deletion primitive.
   591	 */
   592	export function cleanupManagedCrossHostReviewWorktree(gitCwd: string, worktree: string): void {
   593	  const parent = dirname(worktree);
   594	  if (basename(worktree) !== 'worktree'
   595	    || !basename(parent).startsWith('lattice-xhr-review-')
   596	    || dirname(parent) !== tmpdir()) {
   597	    throw new Error(`managed host run: cross-host review snapshot is outside the canonical temporary boundary: ${worktree}`);
   598	  }
   599	  if (!existsSync(worktree)) {
   600	    const registeredWorktrees = execFileSync('git', ['worktree', 'list', '--porcelain'], {
   601	      cwd: gitCwd,
   602	      encoding: 'utf8',
   603	      stdio: ['ignore', 'pipe', 'pipe'],
   604	      maxBuffer: 8 * 1024 * 1024,
   605	    });
   606	    const registered = registeredWorktrees
   607	      .split('\n')
   608	      .some(line => line === `worktree ${resolve(worktree)}`);
   609	    if (!registered) {
   610	      rmSync(parent, { recursive: true, force: true });
   611	      return;
   612	    }
   613	  }
   614	  // Git administration is authoritative for a registered worktree. If this
   615	  // mutation fails, retain the filesystem snapshot and surface the error to GC
   616	  // diagnostics; deleting only the directory would strand hidden registration
   617	  // state while falsely reporting successful cleanup.
   618	  execFileSync('git', ['worktree', 'remove', '--force', worktree], {
   619	    cwd: gitCwd,
   620	    encoding: 'utf8',
   621	    stdio: ['ignore', 'pipe', 'pipe'],
   622	    maxBuffer: 8 * 1024 * 1024,
   623	  });
   624	  rmSync(parent, { recursive: true, force: true });
   625	}
